import{c as i,Q as l,j as t,m as n}from"./chunks/framework.DOi4mjdC.js";const T=JSON.parse('{"title":"概述","description":"","frontmatter":{},"headers":[{"level":1,"title":"概述","slug":"概述"}],"relativePath":"guide/算子实践参考/SIMD算子实现/概述.md","filePath":"guide/算子实践参考/SIMD算子实现/概述.md"}'),a={name:"guide/算子实践参考/SIMD算子实现/概述.md"};function r(o,e,s,p,_,c){return l(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="概述" tabindex="-1">概述 <a class="header-anchor" href="#概述" aria-label="Permalink to &quot;概述&quot;">​</a></h1><p>Ascend C的算子实现主要包含两个部分：</p><ul><li><p>Host侧Tiling实现</p><p>由于NPU中AI Core内部存储无法完全容纳算子输入输出的所有数据，需要每次搬运一部分输入数据进行计算然后搬出，再搬运下一部分输入数据进行计算，这个过程就称之为Tiling。切分数据的算法称为Tiling算法或者Tiling策略。根据算子的shape等信息来确定数据切分算法相关参数（比如每次搬运的块大小，以及总共循环多少次）的计算程序，称之为Tiling实现，也叫Tiling函数（Tiling Function）。由于Tiling实现中完成的均为标量计算，AI Core并不擅长，所以我们将其独立出来放在Host侧CPU上执行。</p></li><li><p>Device侧Kernel实现</p><p>Kernel实现即算子核函数实现，在Kernel函数内部通过解析Host侧传入的Tiling结构体获取Tiling信息，根据Tiling信息控制数据搬入搬出Local Memory的流程；通过调用计算、数据搬运、内存管理、任务同步API，实现算子逻辑。其核心逻辑基本上都为计算密集型任务，需要在NPU上执行。</p></li></ul><p>本章介绍矢量编程、矩阵编程、融合算子编程三种典型场景下的算子Tiling、Kernel实现，是对上文中典型<a href="./../../编程指南/编程模型/AI-Core-SIMD编程/概述.html">编程范式</a>的具体应用，同时也介绍了编程的更多细节、API的使用方法等。</p>',4)])])}const g=i(a,[["render",r]]);export{T as __pageData,g as default};
